/**
 * Nationwide Philippine address lookups.
 *
 * - Geography: PSGC (regions, provinces, cities/municipalities, barangays).
 * - Postal codes: PHLPost-derived data, with GeoNames only as a fallback for cities PHLPost data lacks.
 * - Metro Manila (NCR) has no provinces; it keeps its dedicated, richer dataset (ncr-*.json).
 *
 * Data is generated by backend/scripts/build-ph-address-data.mjs; see backend/src/data/README.md.
 */
import geo from "./ph-geo.json";
import { isNcrProvince, ncrCityOptions } from "./ncr-address";

export const NCR_LABEL = "Metro Manila (NCR)";

interface GeoCity {
  code: string;
  name: string;
  provinceCode: string | null;
  regionCode: string;
  isCity: boolean;
  zip?: string[];
  zipSource?: "phlpost" | "geonames";
}
interface GeoProvince {
  code: string;
  name: string;
  regionCode: string;
}

const PROVINCES = geo.provinces as GeoProvince[];
const CITIES = geo.cities as GeoCity[];

/** Accent/case/"City of"/"Province of" insensitive key used for tolerant matching of saved values. */
export const normalizeLocationKey = (value?: string | null): string =>
  String(value ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\(.*?\)/g, " ")
    .replace(/\bcity of\b|\bmunicipality of\b|\bprovince of\b|\bprovince\b|\bcity\b/g, " ")
    .replace(/\bsto\.?\b/g, "santo")
    .replace(/\bsta\.?\b/g, "santa")
    .replace(/\bdel\b|\bde\b/g, "d")
    .replace(/[^a-z0-9]+/g, "");

/** "City of Cebu" -> "Cebu City"; municipalities and special names are unchanged. */
export const displayCityName = (name: string): string => {
  const match = /^City of (.+)$/.exec(name);
  return match ? `${match[1]} City` : name;
};

interface ProvinceEntry {
  label: string;
  cities: GeoCity[];
}

const citiesByProvince = new Map<string, GeoCity[]>();
for (const city of CITIES) {
  if (!city.provinceCode) continue;
  const list = citiesByProvince.get(city.provinceCode) ?? [];
  list.push(city);
  citiesByProvince.set(city.provinceCode, list);
}

// Province-like entries: every PSGC province plus independent cities that have no province (e.g. Isabela City).
const provinceEntries: ProvinceEntry[] = [
  ...PROVINCES.map((province) => ({ label: province.name, cities: citiesByProvince.get(province.code) ?? [] })),
  ...CITIES.filter((city) => !city.provinceCode).map((city) => ({ label: displayCityName(city.name), cities: [city] })),
];
const provinceByKey = new Map(provinceEntries.map((entry) => [normalizeLocationKey(entry.label), entry]));

/** Province-or-region dropdown options: NCR first, then every province alphabetically. */
export const PROVINCE_OPTIONS: string[] = [
  NCR_LABEL,
  ...provinceEntries.map((entry) => entry.label).sort((a, b) => a.localeCompare(b, "en")),
];

const findProvince = (province?: string | null): ProvinceEntry | undefined =>
  province ? provinceByKey.get(normalizeLocationKey(province)) : undefined;

/** True when the province is one we have city data for (NCR or a PSGC province). */
export const isKnownProvince = (province?: string | null): boolean =>
  isNcrProvince(province) || Boolean(findProvince(province));

/** Cities and municipalities for a province (NCR returns its own localities). */
export const getCityOptions = (province?: string | null): string[] => {
  if (isNcrProvince(province)) return ncrCityOptions;
  const entry = findProvince(province);
  return entry
    ? entry.cities.map((city) => displayCityName(city.name)).sort((a, b) => a.localeCompare(b, "en"))
    : [];
};

/** Resolves a saved/selected city to its PSGC entry inside the given province. */
export const findCity = (province?: string | null, city?: string | null): GeoCity | undefined => {
  const entry = findProvince(province);
  if (!entry || !city?.trim()) return undefined;
  const lowered = city.trim().toLowerCase();
  const exact = entry.cities.find(
    (item) => displayCityName(item.name).toLowerCase() === lowered || item.name.toLowerCase() === lowered
  );
  if (exact) return exact;
  const key = normalizeLocationKey(city);
  return key ? entry.cities.find((item) => normalizeLocationKey(item.name) === key) : undefined;
};

/** Postal codes on file for a city/municipality outside NCR (empty when none; the user enters it manually). */
export const getCityPostalCodes = (province?: string | null, city?: string | null): string[] =>
  findCity(province, city)?.zip ?? [];

const barangayLoaders = import.meta.glob<Record<string, string[]>>("./ph-barangays/*.json", { import: "default" });
const barangayCache = new Map<string, Promise<Record<string, string[]>>>();

/** Barangays for a city/municipality outside NCR. Region files load lazily on first use. */
export const loadBarangays = async (province?: string | null, city?: string | null): Promise<string[]> => {
  const match = findCity(province, city);
  if (!match) return [];
  const path = `./ph-barangays/${match.regionCode}.json`;
  const loader = barangayLoaders[path];
  if (!loader) return [];
  if (!barangayCache.has(path)) barangayCache.set(path, loader());
  const table = await barangayCache.get(path)!;
  return table[match.code] ?? [];
};

/** A province/city pair is valid when the city belongs to the (known) province; unknown provinces are not checked. */
export const isCityInProvince = (province?: string | null, city?: string | null): boolean => {
  if (!province || !city) return true;
  if (isNcrProvince(province)) return true; // NCR cities are validated by the NCR dataset
  if (!findProvince(province)) return true;
  return Boolean(findCity(province, city));
};
